IF OBJECT_ID(N'commerce.StorefrontAvailabilitySchedules', N'U') IS NULL THROW 67000, N'V67 validation failed: schedule table is missing.', 1;
IF OBJECT_ID(N'commerce.StorefrontAvailabilityScheduleProducts', N'U') IS NULL THROW 67001, N'V67 validation failed: product assignment table is missing.', 1;
IF OBJECT_ID(N'commerce.StorefrontAvailabilityScheduleCategories', N'U') IS NULL THROW 67002, N'V67 validation failed: category assignment table is missing.', 1;
IF NOT EXISTS(SELECT 1 FROM sys.check_constraints WHERE name=N'CK_StorefrontAvailabilitySchedules_WeekdayMask') THROW 67003, N'V67 validation failed: weekday validation is missing.', 1;
IF COL_LENGTH(N'commerce.StorefrontAvailabilitySchedules', N'OrderStartTime') IS NULL OR COL_LENGTH(N'commerce.StorefrontAvailabilitySchedules', N'OrderEndTime') IS NULL OR COL_LENGTH(N'commerce.StorefrontAvailabilitySchedules', N'DeliveryStartTime') IS NULL OR COL_LENGTH(N'commerce.StorefrontAvailabilitySchedules', N'DeliveryEndTime') IS NULL THROW 67004, N'V67 validation failed: separate order and delivery windows are missing.', 1;
IF COL_LENGTH(N'commerce.StorefrontAvailabilitySchedules', N'TenantId') IS NULL OR COL_LENGTH(N'commerce.StorefrontAvailabilityScheduleProducts', N'TenantId') IS NULL OR COL_LENGTH(N'commerce.StorefrontAvailabilityScheduleCategories', N'TenantId') IS NULL THROW 67005, N'V67 validation failed: tenant ownership columns are missing.', 1;
IF NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_StorefrontAvailabilitySchedules_Tenant') OR NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_StorefrontAvailabilityScheduleProducts_Tenant') OR NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_StorefrontAvailabilityScheduleCategories_Tenant') THROW 67006, N'V67 validation failed: tenant ownership constraints are missing.', 1;
IF NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_StorefrontAvailabilityScheduleProducts_Schedule') OR NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_StorefrontAvailabilityScheduleProducts_Product') OR NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_StorefrontAvailabilityScheduleCategories_Schedule') OR NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name=N'FK_StorefrontAvailabilityScheduleCategories_Category') THROW 67007, N'V67 validation failed: schedule assignment constraints are missing.', 1;
SELECT N'V67_STOREFRONT_SCHEDULED_AVAILABILITY_VALID' AS ValidationResult;
